<?php
namespace Ishep\Http\Controllers;use Throwable;use DomainException;use Ishep\Bootstrap\Application as App;use Ishep\Http\{Request,Response};
final class DocumentReviewController
{private function app():App{return App::instance();}private function uid():int{return(int)$this->app()->session()->get('user_id');}public function index(Request $r):Response{return$this->app()->render('admin/documents/index',['documents'=>$this->app()->documents()->queue(trim((string)($r->query['status']??'pending')),trim((string)($r->query['q']??'')),(int)($r->query['type']??0),(int)($r->query['membership_type']??0)),'counts'=>$this->app()->documents()->counts(),'types'=>$this->app()->documents()->types(0),'membershipTypes'=>$this->app()->memberships()->active(),'documentStatuses'=>$this->app()->documentStatuses(),'filter'=>$r->query]);}public function show(Request $r):Response{$d=$this->app()->documents()->byReference((string)$r->get('reference'));return$d?$this->app()->render('admin/documents/show',['document'=>$d,'events'=>$this->app()->documents()->events((int)$d['id'],true),'documentStatuses'=>$this->app()->documentStatuses()]):$this->app()->render('errors/404',[],404);}public function download(Request $r):Response{$d=$this->app()->documents()->byReference((string)$r->get('reference'));return$d?(new MemberDocumentController())->file($d):$this->app()->render('errors/404',[],404);}private function action(Request $r,string $to):Response{$ref=(string)$r->get('reference');if(!$this->app()->documents()->byReference($ref))return$this->app()->render('errors/404',[],404);try{$this->app()->documentService()->review($ref,$this->uid(),$to,(string)($r->input['rejection_reason']??''),(string)($r->input['internal_note']??''),$r->ip());$this->app()->session()->flash('status','Document verification status updated.');}catch(Throwable $e){$message=$e instanceof DomainException?$e->getMessage():'The verification action could not be completed safely.';$this->app()->session()->flash('errors',['document'=>[$message]]);}return Response::redirect(url('/admin/documents/'.$ref));}public function verify(Request $r):Response{return$this->action($r,'verified');}public function reject(Request $r):Response{return$this->action($r,'rejected');}}
